(506620, 49933, 12733, '<td valign="top">Great high contrast effect. What is this pyramid, and where?</td>', 'Great high contrast effect. What is this pyramid, and where?', '2003-12-08 08:55:21.000000', NULL, 1),
(506622, 49977, 12733, '<td valign="top">A nice interplay of shapes, but the photo doesn''t grab me; I IMHO the subject doesn''t hold a lot of interest.</td>', 'A nice interplay of shapes, but the photo doesn''t grab me; I IMHO the subject doesn''t hold a lot of interest.', '2003-12-08 08:57:36.000000', NULL, 1),
(506623, 49814, 12733, '<td valign="top">I like the bird. I think the blank white background doesn''t do it justice, and what happened to its feet????</td>', 'I like the bird. I think the blank white background doesn''t do it justice, and what happened to its feet????', '2003-12-08 08:59:03.000000', NULL, 1),
(506627, 49633, 13440, '<td valign="top">I like the color of the background  :)<br/>Putting 2 jars together to make another shapes which is really nice.<br/>Well captured!</td>', 'I like the color of the background  :)Putting 2 jars together to make another shapes which is really nice.Well captured!', '2003-12-08 09:02:48.000000', NULL, 1),
(506629, 49923, 12733, '<td valign="top">Nice capture of the shapes of the apples. As a photograph, I think it would be more attractive if the apples were on a cloth with a distinct texture; this is too plain to contrast with the smooth texture of the apples.</td>', 'Nice capture of the shapes of the apples. As a photograph, I think it would be more attractive if the apples were on a cloth with a distinct texture; this is too plain to contrast with the smooth texture of the apples.', '2003-12-08 09:03:33.000000', NULL, 1),
(506630, 49826, 13440, '<td valign="top">I really like this one, the light and shadow are nice and the unusual shape of sands... Well captured!</td>', 'I really like this one, the light and shadow are nice and the unusual shape of sands... Well captured!', '2003-12-08 09:04:31.000000', NULL, 1),
(506631, 49638, 12733, '<td valign="top">The snowman is cute, the lights are a nice touch, but the hot spot at the bottom and the out-of-focus object in the background detract from the overall effect.</td>', 'The snowman is cute, the lights are a nice touch, but the hot spot at the bottom and the out-of-focus object in the background detract from the overall effect.', '2003-12-08 09:05:03.000000', NULL, 1),
(506634, 49897, 13440, '<td valign="top">Very interesting shot, i like the tone of the blue color here. The freeze of water also nice. Very well done!</td>', 'Very interesting shot, i like the tone of the blue color here. The freeze of water also nice. Very well done!', '2003-12-08 09:07:38.000000', NULL, 1),
(506638, 49525, 1570, '<td valign="top">these are the thingies you supposed to put pairs of socks thru to keep them organized, right?</td>', 'these are the thingies you supposed to put pairs of socks thru to keep them organized, right?', '2003-12-08 09:08:32.000000', NULL, 1),
(506639, 49894, 12733, '<td valign="top">The lighting brings out the texture of the liquid and the highlights in the glass. A clever pun on the word round in the title.  I find the background somewhat cold, and the blotches around the edges are not strong enough to be deliberate, but strong enough to be distracting.</td>', 'The lighting brings out the texture of the liquid and the highlights in the glass. A clever pun on the word round in the title.  I find the background somewhat cold, and the blotches around the edges are not strong enough to be deliberate, but strong enough to be distracting.', '2003-12-08 09:09:02.000000', NULL, 1),
(506640, 49950, 13440, '<td valign="top">I think you captured too closed, OR did you crop at all?</td>', 'I think you captured too closed, OR did you crop at all?', '2003-12-08 09:09:56.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(506641, 49642, 13440, '<td valign="top">I think you should add more lights into this photo...</td>', 'I think you should add more lights into this photo...', '2003-12-08 09:10:23.000000', NULL, 1),
(506642, 49826, 12733, '<td valign="top">The shapes are really interesting, the texture stands out strongly, and the low, slanting light brings out both beautifully.</td>', 'The shapes are really interesting, the texture stands out strongly, and the low, slanting light brings out both beautifully.', '2003-12-08 09:10:41.000000', NULL, 1),
(506643, 49977, 10785, '<td valign="top">Very nice symmetry using existing architecture.<br/>It looks fairly level on the horizon. My eyes may be decieving me, but it may be a hair off. No worries though, score unaffected by it.</td>', 'Very nice symmetry using existing architecture.It looks fairly level on the horizon. My eyes may be decieving me, but it may be a hair off. No worries though, score unaffected by it.', '2003-12-08 09:10:59.000000', NULL, 1),
(506644, 49988, 10785, '<td valign="top">This is very dark.</td>', 'This is very dark.', '2003-12-08 09:11:37.000000', NULL, 1),
(506645, 49700, 12733, '<td valign="top">Beautiful shapes and lighting - what is it?</td>', 'Beautiful shapes and lighting - what is it?', '2003-12-08 09:11:45.000000', NULL, 1),
(506647, 49896, 13440, '<td valign="top">Do you think it\''d be better if you use another background color to emphasize the subject... Just my opinion</td>', 'Do you think it\''d be better if you use another background color to emphasize the subject... Just my opinion', '2003-12-08 09:11:57.000000', NULL, 1),
(506648, 49484, 12733, '<td valign="top">These shapes are interesting, but the number you have included gives the picture a "busy" quality. The path across the rear is too bright for the rest of the picture and draws the eye away from the natural shapes.</td>', 'These shapes are interesting, but the number you have included gives the picture a "busy" quality. The path across the rear is too bright for the rest of the picture and draws the eye away from the natural shapes.', '2003-12-08 09:13:47.000000', NULL, 1),
(506649, 49880, 10785, '<td valign="top">A little reflection on the front edge is distracting. <br/>The crisp chrome would have look nicer on a very white background. The background is not evenly blown out, but it is good none the less.</td>', 'A little reflection on the front edge is distracting. The crisp chrome would have look nicer on a very white background. The background is not evenly blown out, but it is good none the less.', '2003-12-08 09:14:26.000000', NULL, 1),
(506651, 49846, 10785, '<td valign="top">IMO, I would have preferred the subject on the bottom right.<br/>Good lighting and rich wood tones on the violin.</td>', 'IMO, I would have preferred the subject on the bottom right.Good lighting and rich wood tones on the violin.', '2003-12-08 09:16:36.000000', NULL, 1),
(506654, 49633, 10785, '<td valign="top">Excellent symmetry and good choice of background color make this photo appear to make these look like artifacts from a museum.</td>', 'Excellent symmetry and good choice of background color make this photo appear to make these look like artifacts from a museum.', '2003-12-08 09:18:27.000000', NULL, 1),
(506656, 49846, 12733, '<td valign="top">I like the shape, but the blank white background is kind of cold. I think the shape of the instrument would be better brought out by closing in on part of the main body, without the neck. This would be a case where less is more.</td>', 'I like the shape, but the blank white background is kind of cold. I think the shape of the instrument would be better brought out by closing in on part of the main body, without the neck. This would be a case where less is more.', '2003-12-08 09:20:36.000000', NULL, 1),
(506658, 49625, 10785, '<td valign="top">I would have cropped this thighter and formatted the photo as a landscape, rather than a portrait. I believe you could have gotten 640X480 pixels to make it appear larger.<br/> <br/>Other than that, great texture and shape combine to make this an interesting photo of an ordinary object.</td>', 'I would have cropped this thighter and formatted the photo as a landscape, rather than a portrait. I believe you could have gotten 640X480 pixels to make it appear larger. Other than that, great texture and shape combine to make this an interesting photo of an ordinary object.', '2003-12-08 09:20:55.000000', NULL, 1),
(506660, 49964, 10785, '<td valign="top">A soft focus outtake? <br/> <br/>Great use of shape and texture.<br/> <br/>The title may not need to include the year.</td>', 'A soft focus outtake?  Great use of shape and texture. The title may not need to include the year.', '2003-12-08 09:22:20.000000', NULL, 1),
(506661, 49802, 12733, '<td valign="top">Beautiful rendition; the spherical shape is shown well in this picture.</td>', 'Beautiful rendition; the spherical shape is shown well in this picture.', '2003-12-08 09:22:25.000000', NULL, 1),
(506662, 49802, 10785, '<td valign="top">This looks overly photoshopped in my opinion. (Unless you actually took this shot through a telescope.)<br/></td>', 'This looks overly photoshopped in my opinion. (Unless you actually took this shot through a telescope.)', '2003-12-08 09:24:34.000000', NULL, 1),
(506664, 49897, 10785, '<td valign="top">Border is too big. But an excellent photo.</td>', 'Border is too big. But an excellent photo.', '2003-12-08 09:25:56.000000', NULL, 1),
(506665, 49981, 12733, '<td valign="top">This is a nice rendition of the shapes, and the colors and lighting are great.</td>', 'This is a nice rendition of the shapes, and the colors and lighting are great.', '2003-12-08 09:26:05.000000', NULL, 1),
(506666, 49948, 12733, '<td valign="top">Nice rendition of the building; I think the trees actually diminish the sense of shape.</td>', 'Nice rendition of the building; I think the trees actually diminish the sense of shape.', '2003-12-08 09:28:12.000000', NULL, 1),
(506667, 49910, 12733, '<td valign="top">Nice use of shadow to render the shape. The background texture adds interest.</td>', 'Nice use of shadow to render the shape. The background texture adds interest.', '2003-12-08 09:29:27.000000', NULL, 1),
(506670, 49803, 12733, '<td valign="top">Great idea, and a nice composition. I think the large amount of black around it  reduces the effectiveness.</td>', 'Great idea, and a nice composition. I think the large amount of black around it  reduces the effectiveness.', '2003-12-08 09:32:31.000000', NULL, 1),
(506671, 49818, 12733, '<td valign="top">The shadow brings out the shape and contrasts nicely with the shiny plastic of the cutter.</td>', 'The shadow brings out the shape and contrasts nicely with the shiny plastic of the cutter.', '2003-12-08 09:33:27.000000', NULL, 1),
(506674, 49980, 12733, '<td valign="top">Nice isolation of the interesting shapes.</td>', 'Nice isolation of the interesting shapes.', '2003-12-08 09:34:12.000000', NULL, 1),
(506677, 49917, 10785, '<td valign="top">This looks somewhat underexposed. Maybe it''s just not focused well.</td>', 'This looks somewhat underexposed. Maybe it''s just not focused well.', '2003-12-08 09:36:15.000000', NULL, 1),
(506678, 49904, 12733, '<td valign="top">Nice, an almost abstract effect.</td>', 'Nice, an almost abstract effect.', '2003-12-08 09:36:43.000000', NULL, 1),
(506679, 49951, 10785, '<td valign="top">Cute!</td>', 'Cute!', '2003-12-08 09:36:46.000000', NULL, 1),
(506680, 49823, 12733, '<td valign="top">Nice repetition pattern and color of the flowers. I think this would be a stronger photo if it were cropped just above the base, with a symmetrical amount of crop at the top.</td>', 'Nice repetition pattern and color of the flowers. I think this would be a stronger photo if it were cropped just above the base, with a symmetrical amount of crop at the top.', '2003-12-08 09:41:00.000000', NULL, 1),
(506682, 49976, 12733, '<td valign="top">An interesting effect, but too minimalist for my taste.</td>', 'An interesting effect, but too minimalist for my taste.', '2003-12-08 09:42:10.000000', NULL, 1),
(506684, 49940, 12733, '<td valign="top">Interesting shapes, fascinating colors. What is it???</td>', 'Interesting shapes, fascinating colors. What is it???', '2003-12-08 09:43:32.000000', NULL, 1),
(506686, 49883, 12733, '<td valign="top">Interesting shapes and beautiful textures. Gives the feeling of a painting.</td>', 'Interesting shapes and beautiful textures. Gives the feeling of a painting.', '2003-12-08 09:44:47.000000', NULL, 1),
(506690, 49981, 10785, '<td valign="top">Why cut off the top? Having the green tubes surrounding the red and purple would have made for a much better composition.</td>', 'Why cut off the top? Having the green tubes surrounding the red and purple would have made for a much better composition.', '2003-12-08 09:48:00.000000', NULL, 1),
(506691, 49883, 10785, '<td valign="top">Excellent color, composition and DOF.</td>', 'Excellent color, composition and DOF.', '2003-12-08 09:48:28.000000', NULL, 1),
(506694, 49525, 12733, '<td valign="top">Bean bag ashtrays? An interesting pattern shot with interesting shapes. Black and white works well, and the high key adds to the effect.</td>', 'Bean bag ashtrays? An interesting pattern shot with interesting shapes. Black and white works well, and the high key adds to the effect.', '2003-12-08 09:50:51.000000', NULL, 1),
(506697, 49969, 10785, '<td valign="top">Cropped too tightly. Slightly oversharpened.<br/>Nice holiday theme!</td>', 'Cropped too tightly. Slightly oversharpened.Nice holiday theme!', '2003-12-08 09:54:21.000000', NULL, 1),
(506700, 49525, 13925, '<td valign="top">Are they lego pieces?  Clever..clever.  Great way to encourage comments!!  I wonder what a different background color would look like.</td>', 'Are they lego pieces?  Clever..clever.  Great way to encourage comments!!  I wonder what a different background color would look like.', '2003-12-08 09:55:57.000000', NULL, 1),
(506703, 49816, 10785, '<td valign="top">This needs color!</td>', 'This needs color!', '2003-12-08 09:56:57.000000', NULL, 1),
(506704, 49732, 12733, '<td valign="top">The nuts form an interesting pattern, and the metallic texture is well captured. I think a plain white, black or grey background would work better than the vivid color you have.</td>', 'The nuts form an interesting pattern, and the metallic texture is well captured. I think a plain white, black or grey background would work better than the vivid color you have.', '2003-12-08 09:57:28.000000', NULL, 1),
(506705, 49948, 10785, '<td valign="top">It''s really too bad the trees were in the way!</td>', 'It''s really too bad the trees were in the way!', '2003-12-08 09:58:13.000000', NULL, 1),
(506706, 49717, 12733, '<td valign="top">Nice capture of the shapes, and the colors and lighting are brilliant. I think a square crop (less black on the left) would make this a stronger photo.</td>', 'Nice capture of the shapes, and the colors and lighting are brilliant. I think a square crop (less black on the left) would make this a stronger photo.', '2003-12-08 09:58:42.000000', NULL, 1),
(506708, 49514, 12733, '<td valign="top">An interesting photo, but too much sky, not enough detail in the pole. Perhaps a very tight crop would help. The date stamp totally ruins the photo.</td>', 'An interesting photo, but too much sky, not enough detail in the pole. Perhaps a very tight crop would help. The date stamp totally ruins the photo.', '2003-12-08 10:00:00.000000', NULL, 1),
(506710, 49923, 10785, '<td valign="top">The square border conflicts with the round arrangement.</td>', 'The square border conflicts with the round arrangement.', '2003-12-08 10:00:26.000000', NULL, 1),
(506712, 49625, 12733, '<td valign="top">I shot a similar photo for the "Simplicity" challenge,  but haven''t entered it yet. I may try something else now that I see your entry for this challenge. It''s a nice shape, and the rusty texture adds to the effect.</td>', 'I shot a similar photo for the "Simplicity" challenge,  but haven''t entered it yet. I may try something else now that I see your entry for this challenge. It''s a nice shape, and the rusty texture adds to the effect.', '2003-12-08 10:02:23.000000', NULL, 1),
(506713, 49514, 10785, '<td valign="top">Turn off the date stamp!!</td>', 'Turn off the date stamp!!', '2003-12-08 10:02:58.000000', NULL, 1),
(506716, 49854, 10785, '<td valign="top">The humorous title makes this photo!</td>', 'The humorous title makes this photo!', '2003-12-08 10:04:27.000000', NULL, 1),
(506718, 49525, 3569, '<td valign="top">lids</td>', 'lids', '2003-12-08 10:09:36.000000', NULL, 1),
(506719, 49642, 10785, '<td valign="top">This is very dark. I don''t see any reflections.</td>', 'This is very dark. I don''t see any reflections.', '2003-12-08 10:12:57.000000', NULL, 1),
(506722, 49959, 10785, '<td valign="top">Very nice attempt at making the ordinary, extraordinary. I''m thinking school locker vents...<br/> <br/>A slightly unlevel horizon is the only criticism I can offer.</td>', 'Very nice attempt at making the ordinary, extraordinary. I''m thinking school locker vents... A slightly unlevel horizon is the only criticism I can offer.', '2003-12-08 10:17:51.000000', NULL, 1),
(506724, 49704, 7801, '<td valign="top">Great shadow. Different. Meets the challenge well.</td>', 'Great shadow. Different. Meets the challenge well.', '2003-12-08 10:27:49.000000', NULL, 1),
(506726, 49936, 10785, '<td valign="top">The spiral in the foreground bottom really needed to be fully included in the shot. This is slight and somewhat insignificant to an otherwise excellent shot.</td>', 'The spiral in the foreground bottom really needed to be fully included in the shot. This is slight and somewhat insignificant to an otherwise excellent shot.', '2003-12-08 10:33:37.000000', NULL, 1),
(506728, 49888, 10785, '<td valign="top">The entire package should have been included.</td>', 'The entire package should have been included.', '2003-12-08 10:37:09.000000', NULL, 1),
(506730, 49704, 10785, '<td valign="top">That is definitely not a fork for peas!</td>', 'That is definitely not a fork for peas!', '2003-12-08 10:37:43.000000', NULL, 1),
(506735, 49854, 6477, '<td valign="top">Excellent</td>', 'Excellent', '2003-12-08 10:53:47.000000', NULL, 1),
(506743, 49965, 12160, '<td valign="top">Fits the challenge well.</td>', 'Fits the challenge well.', '2003-12-08 11:11:56.000000', NULL, 1),
(506746, 49951, 12160, '<td valign="top">I like the cloud-like texture of the background. nice DOF. 6</td>', 'I like the cloud-like texture of the background. nice DOF. 6', '2003-12-08 11:14:05.000000', NULL, 1),
(506748, 49977, 12160, '<td valign="top">Beautiful symmetry, color and shapes. Well done.</td>', 'Beautiful symmetry, color and shapes. Well done.', '2003-12-08 11:14:53.000000', NULL, 1),
(506750, 49976, 12160, '<td valign="top">Very subtle but it works, beautiful use of negative space and lighting the outline of the kettle (?) to emphasize shape. Very creative composition. I like how the border is done, mind sharing your technic? 7</td>', 'Very subtle but it works, beautiful use of negative space and lighting the outline of the kettle (?) to emphasize shape. Very creative composition. I like how the border is done, mind sharing your technic? 7', '2003-12-08 11:17:20.000000', NULL, 1),
(506753, 49849, 10785, '<td valign="top">I don''t get the title, but it''s a nice abstract view of architecture.</td>', 'I don''t get the title, but it''s a nice abstract view of architecture.', '2003-12-08 11:23:53.000000', NULL, 1),
(506756, 49987, 10785, '<td valign="top">Neat looking kid. Looks like the neighborhood bully! I''m sure he''s a nice guy though.</td>', 'Neat looking kid. Looks like the neighborhood bully! I''m sure he''s a nice guy though.', '2003-12-08 11:25:11.000000', NULL, 1),
(506757, 49962, 10785, '<td valign="top">Excessive border. Otherwise, excellent!</td>', 'Excessive border. Otherwise, excellent!', '2003-12-08 11:26:07.000000', NULL, 1),
(506758, 49869, 10785, '<td valign="top">Soft focus works well here.<br/> <br/>Title des not fit the photo.You don''t really focus on the curves of the guitar or the woman.</td>', 'Soft focus works well here. Title des not fit the photo.You don''t really focus on the curves of the guitar or the woman.', '2003-12-08 11:27:40.000000', NULL, 1),
(506760, 49904, 10785, '<td valign="top">I don''t get the title.<br/>Big border works fairly well here.<br/>Cool symmetry. Right side needs more light.</td>', 'I don''t get the title.Big border works fairly well here.Cool symmetry. Right side needs more light.', '2003-12-08 11:29:00.000000', NULL, 1),
(506763, 49872, 10785, '<td valign="top">Borders on perversion.</td>', 'Borders on perversion.', '2003-12-08 11:31:12.000000', NULL, 1),
(506774, 49727, 772, '<td valign="top">I think this is a beautiful composition.  After going to the trouble to set this up, I would have considered making the surfacr horizon uniform on both sides also.</td>', 'I think this is a beautiful composition.  After going to the trouble to set this up, I would have considered making the surfacr horizon uniform on both sides also.', '2003-12-08 11:41:14.000000', NULL, 1),
(506775, 49919, 3087, '<td valign="top">What great textures! And I really like the limited colour palette. My eyes are saying "black &amp; white" but something else in my mind is saying "colour"! I like the curved diagonal. My only comment would be that I''d like to see a touch more of the foreground ball included to balance with the top one.</td>', 'What great textures! And I really like the limited colour palette. My eyes are saying "black & white" but something else in my mind is saying "colour"! I like the curved diagonal. My only comment would be that I''d like to see a touch more of the foreground ball included to balance with the top one.', '2003-12-08 11:41:28.000000', NULL, 1),
(506777, 49960, 3087, '<td valign="top">Great use of silhouette to show how recognisable some shapes can be without all the additional visual information on colour, 3D form etc.</td>', 'Great use of silhouette to show how recognisable some shapes can be without all the additional visual information on colour, 3D form etc.', '2003-12-08 11:42:57.000000', NULL, 1),
(506778, 49989, 3087, '<td valign="top">An interesting study that results in a great mix of abstract foreground and traditional background. Is it a scultpure or a wind-chime?</td>', 'An interesting study that results in a great mix of abstract foreground and traditional background. Is it a scultpure or a wind-chime?', '2003-12-08 11:44:10.000000', NULL, 1),
(506779, 49870, 3087, '<td valign="top">Simple, vibrant.</td>', 'Simple, vibrant.', '2003-12-08 11:44:31.000000', NULL, 1),
(506784, 49917, 3087, '<td valign="top">What a great curve and I love the way it''s an abstract composition (with two curved "halves" but also a recognisable object. I like how we can see the texture of the skin and hair and also how the shadow at the right contributes to the abstract shapes. There seems to be a yellow tinge, running parallel to the "edge" of the body, a little way in.</td>', 'What a great curve and I love the way it''s an abstract composition (with two curved "halves" but also a recognisable object. I like how we can see the texture of the skin and hair and also how the shadow at the right contributes to the abstract shapes. There seems to be a yellow tinge, running parallel to the "edge" of the body, a little way in.', '2003-12-08 11:49:30.000000', NULL, 1),
(506787, 49323, 3087, '<td valign="top">Not so keen on the soft focus but do like the geometric abstract nature. The colours and shapes really bring back a certain period of fashion during the 1980s, when I was a teen!</td>', 'Not so keen on the soft focus but do like the geometric abstract nature. The colours and shapes really bring back a certain period of fashion during the 1980s, when I was a teen!', '2003-12-08 11:53:03.000000', NULL, 1),
(506789, 49879, 3087, '<td valign="top">Great capture of movement, nice use of colour and DOF. Can''t quite decide whether composition works for me - it doesn''t feel balanced but that kind of goes with the idea of the movement of the dice...</td>', 'Great capture of movement, nice use of colour and DOF. Can''t quite decide whether composition works for me - it doesn''t feel balanced but that kind of goes with the idea of the movement of the dice...', '2003-12-08 11:53:54.000000', NULL, 1),
(506791, 49973, 3087, '<td valign="top">Beautiful! Love the blurry shapes in the background - DOF is just right. I like the choice to go for black and white, though I''d love to see the image in colour too, just for my own interest. Texture and shape together make this photo work so well for me.</td>', 'Beautiful! Love the blurry shapes in the background - DOF is just right. I like the choice to go for black and white, though I''d love to see the image in colour too, just for my own interest. Texture and shape together make this photo work so well for me.', '2003-12-08 11:55:14.000000', NULL, 1),
(506793, 49938, 3087, '<td valign="top">A lovely composition - that snaking curve combined with your DOF choice, works extremely well for me. I love the way the glass reflects the green beneath, making additional shapes of white reflection, shades of green and black shadows.</td>', 'A lovely composition - that snaking curve combined with your DOF choice, works extremely well for me. I love the way the glass reflects the green beneath, making additional shapes of white reflection, shades of green and black shadows.', '2003-12-08 11:57:04.000000', NULL, 1),
(506794, 49964, 3087, '<td valign="top">This has a very timeless feel about it. Composition is great and I like the way that both texture and shape are important. I''m not sure about that misty/ soft focus effect at the egdes.</td>', 'This has a very timeless feel about it. Composition is great and I like the way that both texture and shape are important. I''m not sure about that misty/ soft focus effect at the egdes.', '2003-12-08 11:58:17.000000', NULL, 1),
(506796, 49922, 3087, '<td valign="top">Wow, very Zen. Makes me feel peaceful. I like the gradient of white to dark to blue in the background.</td>', 'Wow, very Zen. Makes me feel peaceful. I like the gradient of white to dark to blue in the background.', '2003-12-08 11:59:05.000000', NULL, 1),
(506797, 49710, 3087, '<td valign="top">Nice! I like the way the strings are at the right hand side and parallel to the edge of the frame. The position of the left curve is also strong. Personally I think a lower DOF, throwing the blue cloth further out of focus, would look better. Nice image!</td>', 'Nice! I like the way the strings are at the right hand side and parallel to the edge of the frame. The position of the left curve is also strong. Personally I think a lower DOF, throwing the blue cloth further out of focus, would look better. Nice image!', '2003-12-08 12:00:07.000000', NULL, 1),
(506802, 49818, 3087, '<td valign="top">Great idea to use an object AND it''s shadow to form a more abstract overall shape. In this case I think the execution isn''t quite polished enough - the lighting is a little uneven and harsh (maybe put a white sheet over the light source). This makes the colour of the background somewhat uneven too. Image quality also seems low, though I appreciate this may be down to camera resolution.</td>', 'Great idea to use an object AND it''s shadow to form a more abstract overall shape. In this case I think the execution isn''t quite polished enough - the lighting is a little uneven and harsh (maybe put a white sheet over the light source). This makes the colour of the background somewhat uneven too. Image quality also seems low, though I appreciate this may be down to camera resolution.', '2003-12-08 12:02:10.000000', NULL, 1),
(506805, 49936, 3087, '<td valign="top">I didn''t expect much from the thumbnail (though I do always reserve judgement until I''ve taken a good look at the full size image, of course!).<br/>But actually I really like this. I love the effect of the low DOF upon the glitter - the multicolour glitter is perfect for that. Great choice of colour for background and composition works too. This would make a great Xmas card.</td>', 'I didn''t expect much from the thumbnail (though I do always reserve judgement until I''ve taken a good look at the full size image, of course!).But actually I really like this. I love the effect of the low DOF upon the glitter - the multicolour glitter is perfect for that. Great choice of colour for background and composition works too. This would make a great Xmas card.', '2003-12-08 12:04:07.000000', NULL, 1),
(506807, 49962, 3087, '<td valign="top">Shame to ruin an image that could be taken romantically with such a cynical title. Would turn ring over so text, limited though our view of it is, was right way up. Nice composition.</td>', 'Shame to ruin an image that could be taken romantically with such a cynical title. Would turn ring over so text, limited though our view of it is, was right way up. Nice composition.', '2003-12-08 12:05:21.000000', NULL, 1),
(506808, 49972, 3087, '<td valign="top">A very strong shape and simple treatment works best here to bring out colours and shapes.</td>', 'A very strong shape and simple treatment works best here to bring out colours and shapes.', '2003-12-08 12:06:02.000000', NULL, 1),
(506810, 49624, 3087, '<td valign="top">How pretty! Poor focus/ lack of detail on the leaves lets this down for me.</td>', 'How pretty! Poor focus/ lack of detail on the leaves lets this down for me.', '2003-12-08 12:07:07.000000', NULL, 1),
(506812, 49854, 3087, '<td valign="top">Great lighting to just show only those areas that you want us to see. And given the shape of what we do see here, isn''t it incredible how the human mind "fills in" what''s missing so that the mind "sees" an entire face/ head? Gestalt theory or something like that - been too long since I was a student to remember! I like this very much!</td>', 'Great lighting to just show only those areas that you want us to see. And given the shape of what we do see here, isn''t it incredible how the human mind "fills in" what''s missing so that the mind "sees" an entire face/ head? Gestalt theory or something like that - been too long since I was a student to remember! I like this very much!', '2003-12-08 12:08:32.000000', NULL, 1),
(506814, 49540, 3087, '<td valign="top">Very atmospheric. Like a beautiful painting.</td>', 'Very atmospheric. Like a beautiful painting.', '2003-12-08 12:10:42.000000', NULL, 1),
(506815, 49701, 3087, '<td valign="top">Great use of light and shadow! Nice composition too and placement of text on ball also strong.</td>', 'Great use of light and shadow! Nice composition too and placement of text on ball also strong.', '2003-12-08 12:11:09.000000', NULL, 1),
