(507684, 49856, 13218, '<td valign="top">Excellent capture of the drop. but it is frozen ;-) Love it.</td>', 'Excellent capture of the drop. but it is frozen ;-) Love it.', '2003-12-09 05:05:11.000000', NULL, 1),
