(507770, 49981, 10705, '<td valign="top">Very nice!</td>', 'Very nice!', '2003-12-09 08:18:42.000000', NULL, 1),
(507774, 49633, 12061, '<td valign="top">the color of the background seems inconsistent .. its like you used the burn tool on the right side of the photo <br/> <br/>Interesting choice of subject, it represents the theme well. I love the orange you chose as a backdrop, it suits the metallic jugs perfectly</td>', 'the color of the background seems inconsistent .. its like you used the burn tool on the right side of the photo  Interesting choice of subject, it represents the theme well. I love the orange you chose as a backdrop, it suits the metallic jugs perfectly', '2003-12-09 08:22:21.000000', NULL, 1),
(507776, 49959, 12061, '<td valign="top">I don''t think the border suits this image well - at the bottom the shadow seeps into the border, there is no division there. <br/>The image seems to be tilted, its not quite straight <br/>Very interesting choice for this challenge</td>', 'I don''t think the border suits this image well - at the bottom the shadow seeps into the border, there is no division there. The image seems to be tilted, its not quite straight Very interesting choice for this challenge', '2003-12-09 08:24:43.000000', NULL, 1),
(507780, 49756, 12061, '<td valign="top">This image could be a lot better if that pink towel/blanket wasn''t in the background. The color and texture of the material brings attention to itself and throws it off the hat and jacket.<br/>I like the ligthing and focus on the main subject <br/> <br/>6</td>', 'This image could be a lot better if that pink towel/blanket wasn''t in the background. The color and texture of the material brings attention to itself and throws it off the hat and jacket.I like the ligthing and focus on the main subject  6', '2003-12-09 08:28:05.000000', NULL, 1),
(507781, 49939, 12061, '<td valign="top">Nice shot, negative space works well, clear focus<br/>I think a little boost in the contrast would help, it would get rid of the blue tint I am seeing in sections of the photo.<br/>6</td>', 'Nice shot, negative space works well, clear focusI think a little boost in the contrast would help, it would get rid of the blue tint I am seeing in sections of the photo.6', '2003-12-09 08:29:56.000000', NULL, 1),
(507802, 49907, 12061, '<td valign="top">This is such a wonderful shot of a flower .. it has to be one of my favourites now. I love how you did a loose crop<br/>the pink color is beautiful, and the background compliments it<br/>DOF works really well, the angle you took this photo at is nice<br/>Not really spot on in terms of the challenge, but I love this shot<br/> <br/>8</td>', 'This is such a wonderful shot of a flower .. it has to be one of my favourites now. I love how you did a loose cropthe pink color is beautiful, and the background compliments itDOF works really well, the angle you took this photo at is niceNot really spot on in terms of the challenge, but I love this shot 8', '2003-12-09 08:49:10.000000', NULL, 1);
