(510007, 49815, 3306, '<td valign="top">Nice, clean, colorful.</td>', 'Nice, clean, colorful.', '2003-12-10 18:52:21.000000', NULL, 1),
(510023, 49803, 12160, '<td valign="top">Beautiful lighting, exposure and framing. Nice job! 7</td>', 'Beautiful lighting, exposure and framing. Nice job! 7', '2003-12-10 19:08:08.000000', NULL, 1),
(510029, 49914, 12160, '<td valign="top">I think the addition of the different types of leaves may have resulted in a cluttered look. The big spiked leaf by itself would have made a better composition. There''s a lot of different shapes in the photo which is probably the look you''re going for.I like the lighting and the saturation of the green color, exposure is good too.</td>', 'I think the addition of the different types of leaves may have resulted in a cluttered look. The big spiked leaf by itself would have made a better composition. There''s a lot of different shapes in the photo which is probably the look you''re going for.I like the lighting and the saturation of the green color, exposure is good too.', '2003-12-10 19:14:17.000000', NULL, 1),
(510031, 49804, 12160, '<td valign="top">Very unique perspective for a lighthouse, I wouldn''t have known it without reading the title. Fits the challenge well, it''s the shape that''s important! 6</td>', 'Very unique perspective for a lighthouse, I wouldn''t have known it without reading the title. Fits the challenge well, it''s the shape that''s important! 6', '2003-12-10 19:16:48.000000', NULL, 1),
(510037, 49781, 12160, '<td valign="top">Very cool idea. Fits the challenge well.</td>', 'Very cool idea. Fits the challenge well.', '2003-12-10 19:24:55.000000', NULL, 1),
(510042, 49947, 12160, '<td valign="top">Very nice warm colors and lighting except for the hot spot in the middle. Shallow DOF worked well. 7</td>', 'Very nice warm colors and lighting except for the hot spot in the middle. Shallow DOF worked well. 7', '2003-12-10 19:29:39.000000', NULL, 1),
(510043, 49906, 12160, '<td valign="top">Nice texture both on the subject and the background. I guess it was difficult for you to find a more perfect leaf, huh?</td>', 'Nice texture both on the subject and the background. I guess it was difficult for you to find a more perfect leaf, huh?', '2003-12-10 19:31:31.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(510048, 49936, 12160, '<td valign="top">Gorgeous shot. Love the DOF, color, lighting. I''m not so sure about the almost perfect square dimension of this photo. The crop at the bottom is a little too tight. Maybe a portrait orientation will look better. Nice job. 8</td>', 'Gorgeous shot. Love the DOF, color, lighting. I''m not so sure about the almost perfect square dimension of this photo. The crop at the bottom is a little too tight. Maybe a portrait orientation will look better. Nice job. 8', '2003-12-10 19:35:38.000000', NULL, 1),
(510049, 49633, 12160, '<td valign="top">Stunning symmetry, beautiful photo.</td>', 'Stunning symmetry, beautiful photo.', '2003-12-10 19:36:55.000000', NULL, 1),
(510090, 49937, 12160, '<td valign="top">Great photo! 8</td>', 'Great photo! 8', '2003-12-10 20:27:42.000000', NULL, 1),
(510150, 49977, 7304, '<td valign="top">Love the color and the shapes are too cool. A lot of shapes here but it is a winner. 8</td>', 'Love the color and the shapes are too cool. A lot of shapes here but it is a winner. 8', '2003-12-10 21:15:55.000000', NULL, 1),
(510156, 49826, 7304, '<td valign="top">Very nice. Looks to be a duotone maybe. Great capture of natural light and shadows for the many shapes here. 7</td>', 'Very nice. Looks to be a duotone maybe. Great capture of natural light and shadows for the many shapes here. 7', '2003-12-10 21:17:22.000000', NULL, 1),
(510159, 49905, 7304, '<td valign="top">Nice and soft but visually interesting. Love the color and the shades. 7</td>', 'Nice and soft but visually interesting. Love the color and the shades. 7', '2003-12-10 21:18:24.000000', NULL, 1),
(510162, 49782, 7304, '<td valign="top">These shapes are too cool. Love the rainbow colors. 7</td>', 'These shapes are too cool. Love the rainbow colors. 7', '2003-12-10 21:19:12.000000', NULL, 1),
(510168, 49897, 7304, '<td valign="top">Very nice capture of the water droplets. Nice DOF. This a great shot and would have worked for the water challenge also. 7</td>', 'Very nice capture of the water droplets. Nice DOF. This a great shot and would have worked for the water challenge also. 7', '2003-12-10 21:20:39.000000', NULL, 1),
(510171, 49960, 7304, '<td valign="top">Great shape and use of pos/neg space.</td>', 'Great shape and use of pos/neg space.', '2003-12-10 21:21:22.000000', NULL, 1),
(510174, 49981, 7304, '<td valign="top">Nice color and interesting shot. Fits challenge well with the circular shapes being dominant. 7</td>', 'Nice color and interesting shot. Fits challenge well with the circular shapes being dominant. 7', '2003-12-10 21:22:28.000000', NULL, 1),
(510177, 49967, 7304, '<td valign="top">Nice color. Fits challenge with the shapes. 7</td>', 'Nice color. Fits challenge with the shapes. 7', '2003-12-10 21:23:33.000000', NULL, 1),
(510179, 49964, 7304, '<td valign="top">Nice shot. Circle being dominant shape with triangles following up. Nice DOF. 7</td>', 'Nice shot. Circle being dominant shape with triangles following up. Nice DOF. 7', '2003-12-10 21:24:48.000000', NULL, 1),
(510182, 49919, 7304, '<td valign="top">Nice idea. Interesting color. Like the flow of the balls. 7</td>', 'Nice idea. Interesting color. Like the flow of the balls. 7', '2003-12-10 21:25:59.000000', NULL, 1),
(510184, 49816, 326, '<td valign="top">Very nice! Looks like something i''ve done before. Great shapes!</td>', 'Very nice! Looks like something i''ve done before. Great shapes!', '2003-12-10 21:28:33.000000', NULL, 1),
(510185, 49849, 326, '<td valign="top">WOW! COOL LINES!</td>', 'WOW! COOL LINES!', '2003-12-10 21:29:58.000000', NULL, 1),
(510186, 49701, 326, '<td valign="top">Very nice black &amp; white good tones. Good job!</td>', 'Very nice black & white good tones. Good job!', '2003-12-10 21:32:52.000000', NULL, 1),
(510191, 49717, 326, '<td valign="top">A wonderful straightforward shot! Good work.</td>', 'A wonderful straightforward shot! Good work.', '2003-12-10 21:37:29.000000', NULL, 1),
(510193, 49897, 326, '<td valign="top">Stunning work! What more can I say..</td>', 'Stunning work! What more can I say..', '2003-12-10 21:39:23.000000', NULL, 1),
(510205, 49960, 326, '<td valign="top">Awesome Silhouette Shot! Great job!</td>', 'Awesome Silhouette Shot! Great job!', '2003-12-10 21:57:08.000000', NULL, 1),
(510274, 49826, 3306, '<td valign="top">Great angle. Love the pattern and the texture.  My favorite of the challenge.</td>', 'Great angle. Love the pattern and the texture.  My favorite of the challenge.', '2003-12-10 23:32:11.000000', NULL, 1),
(510276, 49933, 3306, '<td valign="top">Great pattern. Taken at a perfect time of day. One of my favorites</td>', 'Great pattern. Taken at a perfect time of day. One of my favorites', '2003-12-10 23:32:58.000000', NULL, 1),
(510281, 49704, 3306, '<td valign="top">I did something similar to this called "Unbent Shadow" in the Shadows II challenge. I like your variation. Very clever.</td>', 'I did something similar to this called "Unbent Shadow" in the Shadows II challenge. I like your variation. Very clever.', '2003-12-10 23:36:27.000000', NULL, 1),
(510283, 49810, 12160, '<td valign="top">Nice composition. I like the perspective you used. 7</td>', 'Nice composition. I like the perspective you used. 7', '2003-12-10 23:38:09.000000', NULL, 1),
(510293, 49762, 12160, '<td valign="top">nice color/composition.</td>', 'nice color/composition.', '2003-12-10 23:47:02.000000', NULL, 1),
(510295, 49986, 12160, '<td valign="top">Stunning photo. 9</td>', 'Stunning photo. 9', '2003-12-10 23:49:01.000000', NULL, 1),
(510301, 49908, 12160, '<td valign="top">Very nice photo. 8</td>', 'Very nice photo. 8', '2003-12-10 23:58:58.000000', NULL, 1),
(510303, 49970, 12160, '<td valign="top">Great job on the lighting. The lights are not blown like most of the shots of this type. 7</td>', 'Great job on the lighting. The lights are not blown like most of the shots of this type. 7', '2003-12-11 00:01:10.000000', NULL, 1),
(510345, 49727, 12160, '<td valign="top">Beautiful photo.</td>', 'Beautiful photo.', '2003-12-11 01:19:33.000000', NULL, 1),
(510457, 49888, 12802, '<td valign="top">Why so tightly cropped?  Also, a little sharper would have brought out so much more details in the ''Ball &amp; The Box''<br/> <br/>Had these been better I would have scored it higher.</td>', 'Why so tightly cropped?  Also, a little sharper would have brought out so much more details in the ''Ball & The Box'' Had these been better I would have scored it higher.', '2003-12-11 04:25:48.000000', NULL, 1),
(510460, 49938, 4871, '<td valign="top">It was the title that sold me on this picture! Very well done.</td>', 'It was the title that sold me on this picture! Very well done.', '2003-12-11 04:31:22.000000', NULL, 1),
(510463, 49971, 12802, '<td valign="top">Really like this, good use of lighting, like the blue on the right hand side.</td>', 'Really like this, good use of lighting, like the blue on the right hand side.', '2003-12-11 04:33:39.000000', NULL, 1),
(510466, 49907, 10887, '<td valign="top">Very beautiful I think. A good shot, sharp and nice.</td>', 'Very beautiful I think. A good shot, sharp and nice.', '2003-12-11 04:37:55.000000', NULL, 1),
(510467, 49967, 12802, '<td valign="top">I like this shot, my first view thought it was computer generate, but looking round the red circle I can see it''s not a perfect circle.  The use of negative space and how it''s not in the centre of the picture it also good.</td>', 'I like this shot, my first view thought it was computer generate, but looking round the red circle I can see it''s not a perfect circle.  The use of negative space and how it''s not in the centre of the picture it also good.', '2003-12-11 04:37:56.000000', NULL, 1),
(510469, 49876, 4871, '<td valign="top">I think that a sharpen on this would have improved it greatly. Very nice balance of lighting.</td>', 'I think that a sharpen on this would have improved it greatly. Very nice balance of lighting.', '2003-12-11 04:41:53.000000', NULL, 1),
(510473, 49674, 9982, '<td valign="top">Beautiful props, beautifully lit, beautifully staged and cropped, but the pic says ''Starbucks'' and the title is ''Starbucks''. What about something like ''The shape of drinks to come'' or something more stimulating?</td>', 'Beautiful props, beautifully lit, beautifully staged and cropped, but the pic says ''Starbucks'' and the title is ''Starbucks''. What about something like ''The shape of drinks to come'' or something more stimulating?', '2003-12-11 04:48:49.000000', NULL, 1),
(510474, 49890, 9982, '<td valign="top">Oh my God I''m seeing things! [10]</td>', 'Oh my God I''m seeing things! [10]', '2003-12-11 04:49:59.000000', NULL, 1),
(510475, 49783, 10887, '<td valign="top">Best so far!</td>', 'Best so far!', '2003-12-11 04:50:26.000000', NULL, 1),
(510480, 49849, 9982, '<td valign="top">I''ve wet my nickers?<br/>[9]</td>', 'I''ve wet my nickers?[9]', '2003-12-11 05:16:38.000000', NULL, 1),
(510481, 49976, 9982, '<td valign="top">Totally awesome shot. Horrid border. [9]</td>', 'Totally awesome shot. Horrid border. [9]', '2003-12-11 05:18:58.000000', NULL, 1),
(510596, 49525, 6100, '<td valign="top">It''s obvious ... they''re overexposed!</td>', 'It''s obvious ... they''re overexposed!', '2003-12-11 09:20:00.000000', NULL, 1),
(510619, 49439, 5999, '<td valign="top">Nice crop. I like the way the lines seem to keep the eye looking into the picture. Well done.</td>', 'Nice crop. I like the way the lines seem to keep the eye looking into the picture. Well done.', '2003-12-11 09:45:06.000000', NULL, 1),
(510624, 49781, 5999, '<td valign="top">Nice abstract. Good composition. The only thing that bothers me is the light patch in the lower right corner.</td>', 'Nice abstract. Good composition. The only thing that bothers me is the light patch in the lower right corner.', '2003-12-11 09:48:41.000000', NULL, 1),
(510625, 49777, 5999, '<td valign="top">Good exposure. Nice white snow.</td>', 'Good exposure. Nice white snow.', '2003-12-11 09:50:56.000000', NULL, 1),
(510627, 49786, 5999, '<td valign="top">Nicely done. Great lighting.</td>', 'Nicely done. Great lighting.', '2003-12-11 09:54:19.000000', NULL, 1),
(510673, 49948, 8323, '<td valign="top">LBC!</td>', 'LBC!', '2003-12-11 11:18:22.000000', NULL, 1),
(510695, 49890, 5112, '<td valign="top">Nice!</td>', 'Nice!', '2003-12-11 11:35:34.000000', NULL, 1),
(510705, 49970, 2553, '<td valign="top">This shot has a warm, intimate feel to it that I like.  The title suggests to me that the ornament is the main subject (and shape) of the photo, but the ornament doesn''t stand out enough amidst everything else that is going on for me to focus on it, and it blends in enough that it is hard to determine a definite outline as a shape.   (Shape is actually considered to be the "outline" of a subject while a 3 -dimensional aspect would be considered to be "form".)  My eyes are actually drawn to the ribbons to the right and left of the ornament, moving my attention away from the intended subject.</td>', 'This shot has a warm, intimate feel to it that I like.  The title suggests to me that the ornament is the main subject (and shape) of the photo, but the ornament doesn''t stand out enough amidst everything else that is going on for me to focus on it, and it blends in enough that it is hard to determine a definite outline as a shape.   (Shape is actually considered to be the "outline" of a subject while a 3 -dimensional aspect would be considered to be "form".)  My eyes are actually drawn to the ribbons to the right and left of the ornament, moving my attention away from the intended subject.', '2003-12-11 11:43:28.000000', NULL, 1),
(510746, 49950, 772, '<td valign="top">This photo meets the challenge, but that seems to be about it.  Maybe I don''t understand what other vision you may have had with it.</td>', 'This photo meets the challenge, but that seems to be about it.  Maybe I don''t understand what other vision you may have had with it.', '2003-12-11 12:10:20.000000', NULL, 1),
(510764, 49634, 4517, '<td valign="top">Nice capture with good detail. If you had desaturated, you may have lost the colour fringing. The moon is virtually colourless as far as i`m aware. Good luck. 9</td>', 'Nice capture with good detail. If you had desaturated, you may have lost the colour fringing. The moon is virtually colourless as far as i`m aware. Good luck. 9', '2003-12-11 12:40:18.000000', NULL, 1),
(510773, 49777, 12332, '<td valign="top">shape not really most important aspect - on re-examining, I like it better - the snow clinging to the hanging leaves does create an interesting set of shapes</td>', 'shape not really most important aspect - on re-examining, I like it better - the snow clinging to the hanging leaves does create an interesting set of shapes', '2003-12-11 12:57:21.000000', NULL, 1),
(510780, 49965, 4517, '<td valign="top">Great shot. 9</td>', 'Great shot. 9', '2003-12-11 13:07:07.000000', NULL, 1),
(510784, 49970, 4517, '<td valign="top">A little untidy looking and could be sharper.5</td>', 'A little untidy looking and could be sharper.5', '2003-12-11 13:10:06.000000', NULL, 1),
(510787, 49876, 4517, '<td valign="top">Simple and very good. 9</td>', 'Simple and very good. 9', '2003-12-11 13:11:08.000000', NULL, 1),
(510848, 49727, 5391, '<td valign="top">Lovely and very carefully composed composition and lighting.  Interesting how you''ve staggared the glasses yet still lined up the tops into a single continuous line.  Great work with the glass, keeping reflections low, also.  8</td>', 'Lovely and very carefully composed composition and lighting.  Interesting how you''ve staggared the glasses yet still lined up the tops into a single continuous line.  Great work with the glass, keeping reflections low, also.  8', '2003-12-11 14:36:58.000000', NULL, 1),
(510909, 49980, 10263, '<td valign="top">I think a closer shot of this roof might have worked better. Less centered would be more effective too I think. Very attractive roof</td>', 'I think a closer shot of this roof might have worked better. Less centered would be more effective too I think. Very attractive roof', '2003-12-11 15:29:09.000000', NULL, 1),
(510917, 49639, 10263, '<td valign="top">My favorite so far. Wonderful earthy tones. Great DoF.</td>', 'My favorite so far. Wonderful earthy tones. Great DoF.', '2003-12-11 15:39:33.000000', NULL, 1),
(510924, 49525, 10263, '<td valign="top">I would say knobs of some sort. Nice designs</td>', 'I would say knobs of some sort. Nice designs', '2003-12-11 15:46:10.000000', NULL, 1),
(510949, 49633, 2553, '<td valign="top">This seems more "form" than "shape", however, it is a very nice shot.  The composition suits the subject well.  The lighting is wonderful, and I like that you didn''t distract from the strength of your subject with some kind of big border.</td>', 'This seems more "form" than "shape", however, it is a very nice shot.  The composition suits the subject well.  The lighting is wonderful, and I like that you didn''t distract from the strength of your subject with some kind of big border.', '2003-12-11 16:17:59.000000', NULL, 1),
(510952, 49818, 2553, '<td valign="top">I like this simple and effective shot, though for me it would have been more so if the shadow was in focus instead of the cutter.  The cookie cutter is "form" and the shadow is "shape".</td>', 'I like this simple and effective shot, though for me it would have been more so if the shadow was in focus instead of the cutter.  The cookie cutter is "form" and the shadow is "shape".', '2003-12-11 16:19:41.000000', NULL, 1),
(510954, 49951, 2553, '<td valign="top">I like the concept, and the color.  For me, the composition is weak - there is just too much space around a fairly small subject, and the extra space doesn''t really enhance the shot. In all honesty, I think I would have preferred to see the background stars moved in to the center more, and above, the main star, and fairly tight crop.</td>', 'I like the concept, and the color.  For me, the composition is weak - there is just too much space around a fairly small subject, and the extra space doesn''t really enhance the shot. In all honesty, I think I would have preferred to see the background stars moved in to the center more, and above, the main star, and fairly tight crop.', '2003-12-11 16:24:00.000000', NULL, 1),
(510955, 49816, 2553, '<td valign="top">Ahhh..you get it!  Shape is outline!  An imaginative shot with enough tonal range (not to mention shapes!) to make it interesting.  The composition  has a somewhat "wallpaper" feel to it, but I honestly can''t suggest any alternatives.  No matter; I like it, it makes me smile.  8</td>', 'Ahhh..you get it!  Shape is outline!  An imaginative shot with enough tonal range (not to mention shapes!) to make it interesting.  The composition  has a somewhat "wallpaper" feel to it, but I honestly can''t suggest any alternatives.  No matter; I like it, it makes me smile.  8', '2003-12-11 16:28:38.000000', NULL, 1),
(510958, 49989, 2553, '<td valign="top">Oh how I wish the trees weren''t there!  Love the shape of this sculpture, hate the distraction of the trees.  Love the fact that you "get" what "shape" is - extra point for that.</td>', 'Oh how I wish the trees weren''t there!  Love the shape of this sculpture, hate the distraction of the trees.  Love the fact that you "get" what "shape" is - extra point for that.', '2003-12-11 16:31:25.000000', NULL, 1),
(510962, 49948, 2553, '<td valign="top">The trees really take away from the powerful image of the "pyramid".  At first, the color seemed odd, but after looking at it a number of times,  I kind of like it.   This shot seems to show "form", but shows "shape" as well.</td>', 'The trees really take away from the powerful image of the "pyramid".  At first, the color seemed odd, but after looking at it a number of times,  I kind of like it.   This shot seems to show "form", but shows "shape" as well.', '2003-12-11 16:34:15.000000', NULL, 1),
(510965, 49707, 2553, '<td valign="top">I''ve had to hold off on commenting on this one so I could come back to it a couple of times to look at it again.  At first I thought it was more "form" than "shape", however, the lighting makes the image feel "flat" so that it ends up looking like an image of geometric shapes.  The black and white is absolutely perfect for the presentation of this shot, and for me, has very pleasing tonal range.  9</td>', 'I''ve had to hold off on commenting on this one so I could come back to it a couple of times to look at it again.  At first I thought it was more "form" than "shape", however, the lighting makes the image feel "flat" so that it ends up looking like an image of geometric shapes.  The black and white is absolutely perfect for the presentation of this shot, and for me, has very pleasing tonal range.  9', '2003-12-11 16:38:25.000000', NULL, 1),
(510968, 49525, 7369, '<td valign="top">I think it is the bottom of a anti-slip bath mat (check //www.floormat.com/safetybath.html) :). While there are plenty of shapes, the photo itself isn''t that appealing. You could have made this picture more interesting by using a different light or POV.</td>', 'I think it is the bottom of a anti-slip bath mat (check //www.floormat.com/safetybath.html) :). While there are plenty of shapes, the photo itself isn''t that appealing. You could have made this picture more interesting by using a different light or POV.', '2003-12-11 16:42:36.000000', NULL, 1),
(510972, 49919, 7369, '<td valign="top">One of my favourites. Great use of light and excellent composition.</td>', 'One of my favourites. Great use of light and excellent composition.', '2003-12-11 16:44:48.000000', NULL, 1),
(510997, 49484, 14970, '<td valign="top">I love it. Reminds me of a simpler time</td>', 'I love it. Reminds me of a simpler time', '2003-12-11 17:22:43.000000', NULL, 1),
(510999, 49969, 6458, '<td valign="top">Interesting. The fact that you took this in the snow is a neat idea. However, you need just a bit more lighting on the snow to bring that fact out. Possibly a flashlight lying on top of the snow facing the basket?  I like the colours on the trimmings, very vidid. I wish colour of the basket was a bit more so. The composition leaves some to be desired. It feels static and boxed in.</td>', 'Interesting. The fact that you took this in the snow is a neat idea. However, you need just a bit more lighting on the snow to bring that fact out. Possibly a flashlight lying on top of the snow facing the basket?  I like the colours on the trimmings, very vidid. I wish colour of the basket was a bit more so. The composition leaves some to be desired. It feels static and boxed in.', '2003-12-11 17:22:57.000000', NULL, 1),
(511000, 49758, 6458, '<td valign="top">Cool. Egg, cup, saucer. Makes it look like a ball. Great abstract.</td>', 'Cool. Egg, cup, saucer. Makes it look like a ball. Great abstract.', '2003-12-11 17:23:43.000000', NULL, 1),
(511088, 49846, 10985, '<td valign="top">Very well presented. Excellent light and sharpness... and shape! (the older they are, the better they play!)</td>', 'Very well presented. Excellent light and sharpness... and shape! (the older they are, the better they play!)', '2003-12-11 20:42:37.000000', NULL, 1),
(511101, 49849, 4967, '<td valign="top">I love the abstractedness of this photo... very very well done.  Great black and white photo well composed, just a great picture, although I''m not sure what it is... I like it. 10<br/></td>', 'I love the abstractedness of this photo... very very well done.  Great black and white photo well composed, just a great picture, although I''m not sure what it is... I like it. 10', '2003-12-11 21:30:37.000000', NULL, 1),
(511117, 49897, 10985, '<td valign="top">Beautiful graphics and color. The blurry part does attract attention, IMHO.</td>', 'Beautiful graphics and color. The blurry part does attract attention, IMHO.', '2003-12-11 22:23:49.000000', NULL, 1),
(511122, 49947, 10985, '<td valign="top">Excellent set-up. I just wish there was a really sharp spot, so the eye can stop there.</td>', 'Excellent set-up. I just wish there was a really sharp spot, so the eye can stop there.', '2003-12-11 22:29:39.000000', NULL, 1),
(511244, 49762, 6870, '<td valign="top">Sillhouette was a good choice for bringing focus to the shapes here. Sky is a strange, lovely color.</td>', 'Sillhouette was a good choice for bringing focus to the shapes here. Sky is a strange, lovely color.', '2003-12-12 00:20:20.000000', NULL, 1),
(511245, 49783, 6870, '<td valign="top">Marvelous detail and textures. Contrasting tones bring out the shape of the leaf quite nicely.</td>', 'Marvelous detail and textures. Contrasting tones bring out the shape of the leaf quite nicely.', '2003-12-12 00:21:20.000000', NULL, 1),
(511246, 49484, 6870, '<td valign="top">Superb tones. Very dramatic and eye catching. To me, these are lines rather than shapes, but I''m picking nits. This is good photography.</td>', 'Superb tones. Very dramatic and eye catching. To me, these are lines rather than shapes, but I''m picking nits. This is good photography.', '2003-12-12 00:22:15.000000', NULL, 1),
(511252, 49933, 6870, '<td valign="top">Nice, dramatic, geometric image! I love the stark colors and boldness.</td>', 'Nice, dramatic, geometric image! I love the stark colors and boldness.', '2003-12-12 00:28:15.000000', NULL, 1),
(511253, 49440, 6870, '<td valign="top">I like this idea a lot. Had you tried having the hole in focus and the background blurred? Anyway, the contrast makes the shape of the hole very evident.</td>', 'I like this idea a lot. Had you tried having the hole in focus and the background blurred? Anyway, the contrast makes the shape of the hole very evident.', '2003-12-12 00:29:08.000000', NULL, 1),
(511254, 49908, 6870, '<td valign="top">Motion blur implies shape very well. The traffic lights add a nice touch!</td>', 'Motion blur implies shape very well. The traffic lights add a nice touch!', '2003-12-12 00:29:45.000000', NULL, 1),
