(512835, 49826, 8860, '<td valign="top">Blue ribbon. Well done!<br/> <br/>This is a simply perfect take on the challenge and a beautiful shot. Great lighting, texture and natural forms expertly taken. Flawless composition means I''d hang this one. [10]</td>', 'Blue ribbon. Well done! This is a simply perfect take on the challenge and a beautiful shot. Great lighting, texture and natural forms expertly taken. Flawless composition means I''d hang this one. [10]', '2003-12-14 17:15:12.000000', NULL, 1),
(512836, 49856, 8860, '<td valign="top">That''s my kind of shape. Simply wonderful - especially with the anticipation of the droplet about to fall. if you had just a touch more DOF this would have been a 10. Love it to bits. [9]</td>', 'That''s my kind of shape. Simply wonderful - especially with the anticipation of the droplet about to fall. if you had just a touch more DOF this would have been a 10. Love it to bits. [9]', '2003-12-14 17:16:22.000000', NULL, 1),
