(512842, 49972, 8860, '<td valign="top">It''s well lit with good definition though, but just a little boring. This lacks creativity and doesn''t exploit the medium of photography enough for me.</td>', 'It''s well lit with good definition though, but just a little boring. This lacks creativity and doesn''t exploit the medium of photography enough for me.', '2003-12-14 17:24:11.000000', NULL, 1),
(512843, 49439, 10402, '<td valign="top">Nice textures as well as interesting shapes.</td>', 'Nice textures as well as interesting shapes.', '2003-12-14 17:25:35.000000', NULL, 1),
(512844, 49985, 8860, '<td valign="top">This is actually a very well lit and crisply taken shot, but has become very washed out and magenta-heavy. As for ''shapes'' this lacks interest for me, but it has the making of a nice still life.</td>', 'This is actually a very well lit and crisply taken shot, but has become very washed out and magenta-heavy. As for ''shapes'' this lacks interest for me, but it has the making of a nice still life.', '2003-12-14 17:26:38.000000', NULL, 1),
(512847, 49816, 10402, '<td valign="top">I like the way the different pasta thicknesses create a nice range of tones. I don''t particularly like the color; it seems a bit bland for the subject. Perhaps a bit more saturation would help.</td>', 'I like the way the different pasta thicknesses create a nice range of tones. I don''t particularly like the color; it seems a bit bland for the subject. Perhaps a bit more saturation would help.', '2003-12-14 17:31:45.000000', NULL, 1),
