(512878, 49985, 10402, '<td valign="top">Great lighting; it shows off the beauty of the bottles and makes a nice gradient background.</td>', 'Great lighting; it shows off the beauty of the bottles and makes a nice gradient background.', '2003-12-14 17:50:27.000000', NULL, 1),
(512881, 49910, 10402, '<td valign="top">The shadow shows off the shape of the lamp very well. Nice textures.</td>', 'The shadow shows off the shape of the lamp very well. Nice textures.', '2003-12-14 17:55:10.000000', NULL, 1),
(512883, 49508, 7106, '<td valign="top">nice focus.</td>', 'nice focus.', '2003-12-14 17:59:31.000000', NULL, 1),
(512884, 49815, 10402, '<td valign="top">Nice assortment of shapes and colors, but seems a bit jumbled. I think the shapes are arranged fine, but there are too many shadows going different directions. Using one strong "key light" to create the shadows and a soft diffuse "fill light" (or reflector) to keep the shadows from being too strong may have made an image with more impact.</td>', 'Nice assortment of shapes and colors, but seems a bit jumbled. I think the shapes are arranged fine, but there are too many shadows going different directions. Using one strong "key light" to create the shadows and a soft diffuse "fill light" (or reflector) to keep the shadows from being too strong may have made an image with more impact.', '2003-12-14 18:05:48.000000', NULL, 1),
(512885, 49540, 10402, '<td valign="top">The low contrast silhouette gives a nice effect.</td>', 'The low contrast silhouette gives a nice effect.', '2003-12-14 18:09:24.000000', NULL, 1),
(512887, 49642, 12733, '<td valign="top">An interesting idea, but it came out really murky and hard to see.</td>', 'An interesting idea, but it came out really murky and hard to see.', '2003-12-14 18:11:57.000000', NULL, 1),
(512890, 49971, 10402, '<td valign="top">The colors give this an interesting abstract look. It took me a minute to see that this is a shell.</td>', 'The colors give this an interesting abstract look. It took me a minute to see that this is a shell.', '2003-12-14 18:17:27.000000', NULL, 1),
(512892, 49674, 12733, '<td valign="top">I like the lighting and the choice of a wooden table, rather than a plain white or black background.The highlights seem a little blown out.</td>', 'I like the lighting and the choice of a wooden table, rather than a plain white or black background.The highlights seem a little blown out.', '2003-12-14 18:19:35.000000', NULL, 1),
